window.addEventListener("hashchange",focusSheet);document.addEventListener("keydown",function(event){if(event.key!=="Escape")return;var sheet=openSheet()||document.querySelector(".sheet.is-open");if(sheet&&isOverlayVisible(sheet)){event.preventDefault();closeSheet(sheet);}});document.addEventListener("keydown",function(event){if(event.key!=="Tab")return;var sheet=openSheet()||document.querySelector(".sheet.is-open");if(!sheet||!isOverlayVisible(sheet))return;var focusables=Array.prototype.filter.call(sheet.querySelectorAll(".sheet__panel a[href], .sheet__panel button:not([disabled]), .sheet__panel input:not([type=hidden]):not([disabled])"),function(el){return el.offsetParent!==null;});if(!focusables.length)return;var first=focusables[0];var last=focusables[focusables.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});var RESUBMIT_MS=3000;document.addEventListener("submit",function(event){var form=event.target;if(!form||!form.getAttribute||(form.getAttribute("method")||"").toLowerCase()!=="post")return;if(form.hasAttribute("hx-post"))return;var last=parseInt(form.getAttribute("data-sent-at")||"0",10);if(Date.now()-last<RESUBMIT_MS){event.preventDefault();return;}
setTimeout(function(){if(!event.defaultPrevented)form.setAttribute("data-sent-at",String(Date.now()));},0);});document.addEventListener("htmx:beforeRequest",function(event){var form=event.target;if(form&&form.classList&&form.classList.contains("register__form"))form.setAttribute("aria-busy","true");});document.addEventListener("htmx:beforeSwap",function(event){var form=event.target;if(!form||!form.classList||!form.classList.contains("register__form"))return;form.removeAttribute("aria-busy");var xhr=event.detail&&event.detail.xhr;if(xhr&&xhr.status>=200&&xhr.status<400){var sheet=form.closest("[data-register]");var back=sheet?sheet.getAttribute("data-return"):null;if(back)location.replace(back);}});document.addEventListener("htmx:afterSettle",function(){init(document);});function startAutoRefresh(){var panel=document.getElementById("painel");var url=panel&&panel.getAttribute("data-refresh-url");if(!url)return;var seconds=parseInt(panel.getAttribute("data-refresh-seconds")||"30",10);var last=Date.now();function busy(){if(document.querySelector(".sheet.is-open")||openSheet())return true;var active=document.activeElement;return!!(active&&active.closest&&active.closest(".register__form"));}
function refresh(){if(document.visibilityState!=="visible"||!window.htmx||busy())return;last=Date.now();window.htmx.ajax("GET",url,{source:panel,swap:"none"});}
setInterval(refresh,seconds*1000);document.addEventListener("visibilitychange",function(){if(document.visibilityState==="visible"&&Date.now()-last>=seconds*1000)refresh();});}
function init(scope){var groups=scope.querySelectorAll("[data-stepper]");for(var i=0;i<groups.length;i++)syncStepper(groups[i]);var alert=scope.querySelector("[data-autofocus]");if(alert)alert.focus();var open=scope.querySelector(".sheet.is-open");if(open&&isOverlayVisible(open)){var input=open.querySelector(".stepper__input");if(input)input.focus();}else{focusSheet();}}
